// What the schedule writes to collection_runs for this source. A page that
// could not be read, or a dashboard that did not answer, is the run's error,
// so the check of the other sources goes on.
const r = $json;
const body = r.body && typeof r.body === 'object' ? r.body : {};
if (r.statusCode === 200 && typeof body.items_found === 'number') {
  return [{ json: { items_found: body.items_found, items_new: body.items_new || 0, error: body.error || null } }];
}
const why = body.detail || (r.error && (r.error.message || r.error)) || `the dashboard answered ${r.statusCode}`;
return [{ json: { items_found: 0, items_new: 0, error: String(why).slice(0, 300) } }];
